{"sql": "WITH months AS (
    SELECT '2020-01' as month
    UNION ALL SELECT '2020-02'
    UNION ALL SELECT '2020-03'
    UNION ALL SELECT '2020-04'
),
customers AS (
    SELECT DISTINCT customer_id FROM customer_transactions
)
SELECT * FROM months CROSS JOIN customers ORDER BY customer_id, month"}

{"sql": "WITH months AS (
    SELECT '2020-01-31' as month_end, 1 as month_num
    UNION ALL SELECT '2020-02-29', 2
    UNION ALL SELECT '2020-03-31', 3
    UNION ALL SELECT '2020-04-30', 4
),
customers AS (
    SELECT DISTINCT customer_id FROM customer_transactions
)
SELECT COUNT(*) as total_customer_months FROM months CROSS JOIN customers"}
